/**
 * Compares engine results with the Octave references (reference/*.json).
 * Reference files are generated by matlab/refs/export_refs.m; nothing here
 * is typed by hand.
 */
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { expect } from 'vitest'
import { sortComplex, type Complex } from '../../src/engine/complex'
import { defaults, type ParamValue } from '../../src/engine/matlabScript'

const root = fileURLToPath(new URL('../../', import.meta.url))

export type RefCells = Record<string, Record<string, unknown>>

export function loadReference(name: string): RefCells {
  return JSON.parse(readFileSync(`${root}reference/${name}.json`, 'utf8')).cells
}

export const loadScript = (path: string): string => readFileSync(`${root}matlab/${path}`, 'utf8')

/** The script's @param defaults, typed as the model's parameters. */
export function scriptDefaults<P>(path: string): P {
  return defaults(loadScript(path)) as unknown as P
}

export interface Tolerance {
  rel: number
  abs: number
}
export const TIGHT: Tolerance = { rel: 1e-9, abs: 1e-10 }

const special = (r: unknown): number | undefined =>
  r === 'NaN' ? NaN : r === 'Infinity' ? Infinity : r === '-Infinity' ? -Infinity : undefined

function num(r: unknown): number {
  const s = special(r)
  if (s !== undefined) return s
  if (typeof r !== 'number') throw new Error(`expected a number, got ${JSON.stringify(r)}`)
  return r
}

function close(e: number, r: number, tol: Tolerance): boolean {
  if (Number.isNaN(e) || Number.isNaN(r)) return Number.isNaN(e) && Number.isNaN(r)
  if (!Number.isFinite(e) || !Number.isFinite(r)) return e === r
  return Math.abs(e - r) <= tol.abs + tol.rel * Math.max(Math.abs(e), Math.abs(r))
}

const asArray = (r: unknown): unknown[] => (Array.isArray(r) ? r : [r])
const isTF = (v: unknown): v is { num: number[]; den: number[]; Ts: number } =>
  !!v && typeof v === 'object' && 'num' in v && 'den' in v && 'Ts' in v
const isComplex = (v: unknown): v is Complex => !!v && typeof v === 'object' && 're' in v && 'im' in v && typeof (v as Complex).re === 'number'

function refComplexList(r: unknown): Complex[] {
  if (r && typeof r === 'object' && !Array.isArray(r) && 're' in r && 'im' in r) {
    const pair = r as { re: unknown; im: unknown }
    const re = asArray(pair.re).map(num)
    const im = asArray(pair.im).map(num)
    return re.map((x, i) => ({ re: x, im: im[i] }))
  }
  return asArray(r).map((x) => ({ re: num(x), im: 0 }))
}

/** Asserts that engine value `e` matches reference value `r`. */
export function compareValue(e: unknown, r: unknown, path: string, tol: Tolerance = TIGHT): void {
  if (isTF(e)) {
    const R = r as { class: string; num: unknown; den: unknown; Ts: unknown }
    expect(R.class, `${path}: class`).toBe('tf')
    compareValue(e.num, R.num, `${path}.num`, tol)
    compareValue(e.den, R.den, `${path}.den`, tol)
    compareValue(e.Ts, R.Ts, `${path}.Ts`, tol)
    return
  }
  if (Array.isArray(e) && (e.length === 0 || isComplex(e[0]))) {
    const ec = sortComplex(e as Complex[])
    const rc = sortComplex(refComplexList(r))
    expect(ec.length, `${path}: number of roots`).toBe(rc.length)
    ec.forEach((z, i) => {
      const ok = close(z.re, rc[i].re, tol) && close(z.im, rc[i].im, tol)
      expect(ok, `${path}[${i}]: ${z.re}${z.im >= 0 ? '+' : ''}${z.im}j vs ${rc[i].re}${rc[i].im >= 0 ? '+' : ''}${rc[i].im}j`).toBe(true)
    })
    return
  }
  if (typeof e === 'boolean' || (Array.isArray(e) && typeof e[0] === 'boolean')) {
    expect(asArray(e), path).toEqual(asArray(r))
    return
  }
  if (typeof e === 'number') {
    const rv = Array.isArray(r) && r.length === 1 ? r[0] : r
    expect(close(e, num(rv), tol), `${path}: ${e} vs ${JSON.stringify(rv)}`).toBe(true)
    return
  }
  if (Array.isArray(e)) {
    const ra = asArray(r)
    // a row of numbers may be stored as a number when it has one element
    expect(e.length, `${path}: length`).toBe(ra.length)
    if (e.every((v) => typeof v === 'number')) {
      // norm-wise: a time series is compared relative to its own scale, so a
      // zero crossing is not held to a relative error on a value near 0
      let scale = 0
      e.forEach((v, i) => {
        const rv = num(ra[i])
        if (Number.isFinite(v)) scale = Math.max(scale, Math.abs(v))
        if (Number.isFinite(rv)) scale = Math.max(scale, Math.abs(rv))
      })
      const t: Tolerance = { rel: tol.rel, abs: tol.abs + tol.rel * scale }
      e.forEach((v, i) => compareValue(v, ra[i], `${path}[${i}]`, t))
      return
    }
    e.forEach((v, i) => compareValue(v, ra[i], `${path}[${i}]`, tol))
    return
  }
  if (e && typeof e === 'object') {
    const R = r as Record<string, unknown>
    const E = e as Record<string, unknown>
    // stepinfo: without overshoot the peak lies in a flat tail where round-off
    // decides the index, so PeakTime is not a meaningful quantity to compare
    const noPeak = 'PeakTime' in E && typeof E.Overshoot === 'number' && E.Overshoot < 1e-6
    for (const k of Object.keys(E)) {
      if (noPeak && k === 'PeakTime') continue
      if (k in R) compareValue(E[k], R[k], `${path}.${k}`, tol)
    }
    return
  }
  throw new Error(`${path}: cannot compare ${typeof e}`)
}

/**
 * Compares every variable the engine returns for a cell that the reference
 * also recorded, and checks that at least `minShared` of them were compared
 * (so a renamed variable cannot silently skip the comparison).
 */
export function expectCell(
  engineCell: Record<string, unknown>,
  refCell: Record<string, unknown> | undefined,
  path: string,
  opts: { tol?: Tolerance; tolFor?: Record<string, Tolerance>; minShared?: number } = {},
): string[] {
  expect(refCell, `${path}: cell missing from the reference`).toBeDefined()
  const shared = Object.keys(engineCell).filter((k) => k in refCell!)
  for (const k of shared) compareValue(engineCell[k], refCell![k], `${path}.${k}`, opts.tolFor?.[k] ?? opts.tol ?? TIGHT)
  expect(shared.length, `${path}: variables compared (${shared.join(', ')})`).toBeGreaterThanOrEqual(opts.minShared ?? 1)
  return shared
}

export type Params = Record<string, ParamValue>
